create table public.profiles (id uuid primary key references auth.users on delete cascade, name text not null check (length(name) between 1 and 100));
create table public.collections (id uuid primary key default gen_random_uuid(), name text not null check (length(name) between 1 and 120), owner_id uuid not null references public.profiles, created_at timestamptz default now());
create table public.members (collection_id uuid references public.collections on delete cascade, user_id uuid references public.profiles on delete cascade, primary key(collection_id,user_id));
create table public.entries (id uuid primary key, collection_id uuid not null references public.collections on delete cascade, creator_id uuid references public.profiles on delete set null, payload text not null, created_at timestamptz default now(), unique(collection_id,id));
create table public.favorites (collection_id uuid not null, entry_id uuid not null, user_id uuid references public.profiles on delete cascade, primary key(entry_id,user_id), foreign key(collection_id,entry_id) references public.entries(collection_id,id) on delete cascade);
create table public.author_assignments (collection_id uuid references public.collections on delete cascade, author text not null, user_id uuid, primary key(collection_id,author), foreign key(collection_id,user_id) references public.members(collection_id,user_id) on delete cascade);
create table public.invites (id uuid primary key default gen_random_uuid(), collection_id uuid references public.collections on delete cascade, token_hash text unique not null, expires_at timestamptz not null default now()+interval '7 days', created_at timestamptz default now());
create index on public.entries(collection_id,created_at);
create index on public.members(user_id);
create function public.is_member(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from members where collection_id=cid and user_id=auth.uid()) $$;
create function public.is_owner(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from collections where id=cid and owner_id=auth.uid()) $$;
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles values(new.id,coalesce(nullif(left(new.raw_user_meta_data->>'name',100),''),'Wandering chronicler')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
insert into public.profiles select id, coalesce(nullif(left(raw_user_meta_data->>'name',100),''),'Wandering chronicler') from auth.users on conflict do nothing;
create function public.owner_membership() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into members values(new.id,new.owner_id); return new; end $$;
create trigger collection_owner after insert on public.collections for each row execute function public.owner_membership();
alter table public.profiles enable row level security;
alter table public.collections enable row level security;
alter table public.members enable row level security;
alter table public.entries enable row level security;
alter table public.favorites enable row level security;
alter table public.author_assignments enable row level security;
alter table public.invites enable row level security;
create policy profiles_read on public.profiles for select to authenticated using (id=auth.uid() or exists(select 1 from members a join members b on a.collection_id=b.collection_id where a.user_id=auth.uid() and b.user_id=profiles.id));
create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy collections_read on public.collections for select to authenticated using(public.is_member(id));
create policy collections_create on public.collections for insert to authenticated with check(owner_id=auth.uid());
create policy collections_update on public.collections for update to authenticated using(public.is_owner(id)) with check(public.is_owner(id) and owner_id=auth.uid());
create policy collections_delete on public.collections for delete to authenticated using(public.is_owner(id));
create policy members_read on public.members for select to authenticated using(public.is_member(collection_id));
create policy entries_read on public.entries for select to authenticated using(public.is_member(collection_id));
create policy entries_create on public.entries for insert to authenticated with check(public.is_member(collection_id) and creator_id=auth.uid());
create policy favorites_read on public.favorites for select to authenticated using(public.is_member(collection_id));
create policy favorites_create on public.favorites for insert to authenticated with check(public.is_member(collection_id) and user_id=auth.uid());
create policy favorites_delete on public.favorites for delete to authenticated using(public.is_member(collection_id) and user_id=auth.uid());
create policy assignments_read on public.author_assignments for select to authenticated using(public.is_member(collection_id));
create policy assignments_manage on public.author_assignments for all to authenticated using(public.is_owner(collection_id)) with check(public.is_owner(collection_id));
create policy invites_manage on public.invites for all to authenticated using(public.is_owner(collection_id)) with check(public.is_owner(collection_id));
create function public.accept_invite(token text) returns uuid language plpgsql security definer set search_path=public as $$ declare cid uuid; begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 select collection_id into cid from invites where token_hash=encode(sha256(convert_to(token,'UTF8')),'hex') and expires_at>now() for share;
 if cid is null then raise exception 'Invitation is invalid, revoked or expired'; end if;
 insert into members values(cid,auth.uid()) on conflict do nothing; return cid;
end $$;
revoke all on function public.accept_invite(text) from public;
grant execute on function public.accept_invite(text) to authenticated;
revoke all on function public.new_profile(), public.owner_membership() from public;
grant select,update on public.profiles to authenticated;
grant select,insert,update,delete on public.collections,public.entries,public.favorites,public.author_assignments,public.invites to authenticated;
grant select on public.members to authenticated;
create function public.delete_my_account() returns void language plpgsql security definer set search_path=public as $$ begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 delete from collections where owner_id=auth.uid();
 delete from auth.users where id=auth.uid();
end $$;
revoke all on function public.delete_my_account() from public;
grant execute on function public.delete_my_account() to authenticated;
